const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const datasets={q3:{names:['Northstar','Field & Co.','Everyday'],mentions:[420,340,240],prevMentions:[280,350,370],reach:[2.4,4.2,1.4],prevReach:[2.8,2.7,1.5]},q2:{names:['Northstar','Field & Co.','Everyday'],mentions:[300,450,250],prevMentions:[340,360,300],reach:[3.6,2.4,2],prevReach:[2.4,3.6,2]}};let metric='mentions',brand=0;const sum=a=>a.reduce((x,y)=>x+y,0);const money=n=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);const percent=n=>Math.round(n*10)/10;
function render(){let d=datasets[$('#period').value],v=d[metric],p=d[metric==='mentions'?'prevMentions':'prevReach'];$('#chart-title').textContent=metric==='mentions'?'SHARE OF VOICE / ARTICLE VOLUME':'SHARE OF ESTIMATED REACH';$('#bars').innerHTML=d.names.map((n,i)=>`<button class="brand-bar ${brand===i?'selected':''}" data-brand="${i}" aria-pressed="${brand===i}" aria-label="Investigate ${n}"><div class="bar-heading"><span>${n}</span><span>${percent(v[i]/sum(v)*100)}% <small>· ${v[i]}${metric==='reach'?'m est. reach':' articles'}</small></span></div><div class="bar-track"><div class="bar-fill" style="width:${v[i]/sum(v)*100}%"></div></div><div class="bar-track previous"><div class="bar-fill" style="width:${p[i]/sum(p)*100}%"></div></div></button>`).join('');const change=percent((v[brand]/p[brand]-1)*100),shareChange=percent((v[brand]/sum(v)-p[brand]/sum(p))*100);$('#insight-title').textContent=`${d.names[brand]}: ${Math.abs(change)}% ${change>=0?'more':'less'} ${metric==='mentions'?'coverage.':'estimated reach.'}`;$('#insight-copy').textContent=`${metric==='mentions'?'Article volume':'Estimated reach'} moved from ${p[brand]}${metric==='reach'?'m':''} to ${v[brand]}${metric==='reach'?'m':''}. Its share changed by ${shareChange>0?'+':''}${shareChange} percentage points. ${metric==='mentions'?'Now switch to estimated reach: volume alone does not tell you the publication mix.':'Estimated reach reflects potential exposure, not unique people reached or proven business impact.'}`;$('#next-question').textContent=metric==='mentions'?'Is the brand gaining presence in the outlets that matter?':'Which publications and topics explain the change in potential exposure?';$('#observation').textContent=$('#insight-copy').textContent;$$('[data-brand]').forEach(b=>b.onclick=()=>{brand=Number(b.dataset.brand);render()})}
$$('[data-metric]').forEach(b=>b.onclick=()=>{metric=b.dataset.metric;$$('[data-metric]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});render()});$('#period').onchange=render;$('#investigate').setAttribute('aria-expanded','false');$('#investigate').onclick=()=>{const p=$('#evidence-panel');p.hidden=!p.hidden;$('#investigate').setAttribute('aria-expanded',!p.hidden);$('#investigate').textContent=p.hidden?'See the evidence pattern ↗':'Close the evidence pattern ↑'};
const keys=['reports','hours','saving','rate','cost'];const presets={lean:[4,8,40,35,300],agency:[12,10,50,45,750],scale:[30,14,60,55,1800]};let result;function calc(){let [r,h,s,rate,cost]=keys.map(k=>Math.max(0,Number($('#'+k).value)||0));$('#reports-out').textContent=r;$('#hours-out').textContent=h+' h';$('#saving-out').textContent=s+'%';let saved=r*h*s/100,gross=saved*rate*12,net=gross-cost*12,roi=cost?net/(cost*12)*100:null,be=r*h*rate?cost/(r*h*rate)*100:null;$('#gross').textContent=money(gross);$('#saved').textContent=percent(saved)+' h';$('#net').textContent=money(net);$('#return').textContent=roi===null?'N/A — no investment':Math.round(roi)+'%';$('#break-even').textContent=be===null?'N/A — no baseline value':percent(be)+'%'+(be>100?' (above full capacity)':'');result={r,h,s,rate,cost,saved,gross,net,roi,be}}keys.forEach(k=>$('#'+k).oninput=()=>{$$('[data-preset]').forEach(b=>b.classList.remove('active'));calc()});$$('[data-preset]').forEach(b=>b.onclick=()=>{keys.forEach((k,i)=>$('#'+k).value=presets[b.dataset.preset][i]);$$('[data-preset]').forEach(x=>x.classList.toggle('active',x===b));calc()});$('#download').onclick=()=>{const r=result;const content=`PR IRIS — ILLUSTRATIVE BUSINESS CASE\n\nReports per month: ${r.r}\nCurrent hours per report: ${r.h}\nAssumed time reduction: ${r.s}%\nLoaded hourly cost: ${money(r.rate)}\nMonthly investment assumption: ${money(r.cost)}\n\nMonthly hours freed: ${percent(r.saved)}\nAnnual capacity value: ${money(r.gross)}\nAnnual net value after investment: ${money(r.net)}\nModeled ROI: ${r.roi===null?'N/A':Math.round(r.roi)+'%'}\nBreak-even reduction: ${r.be===null?'N/A':percent(r.be)+'%'}\n\nMethod: reports × hours × reduction × hourly cost × 12.\nNet value subtracts 12 months of investment. ROI divides net value by annual investment.\n\nAssumptions, not pricing or measured results. Capacity value is not automatically cash savings. Excludes revenue attribution, setup costs and any costs outside the monthly investment input. Human review remains part of the work.\n`;const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type:'text/plain'}));a.href=url;a.download='PR-Iris-Business-Case.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};window.addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-innerHeight;$('#progress').style.width=(max>0?scrollY/max*100:0)+'%'},{passive:true});render();calc();

const chatExamples=[{q:'How did Northstar do in Q3 compared with last year?',a:'In these two selected batches, Northstar went from 280 articles to 420. That is more coverage—but let’s check estimated reach before calling it a stronger result.',stat:'280 → 420 articles · +50%',caution:'Article volume tells us how often the brand appeared, not how many people saw it.',source:'Fictional demo batches: Coverage_Q3_2025.xlsx and Coverage_Q3_2026.xlsx. Brand: Northstar. Same illustrative figures as the Q3 coverage explorer.'},{q:'And what happened to its estimated reach?',a:'Using the same two batches and brand, estimated reach fell from 2.8m to 2.4m. So Northstar appeared more often, while the estimated exposure was lower.',stat:'2.8m → 2.4m estimated reach · −14.3%',caution:'This could reflect a different mix of publications. The numbers alone don’t establish the cause.',source:'Same selected Q3 batches and Northstar filter. Estimated reach is potential exposure, not unique audience. All figures are fictional.'},{q:'What should we investigate before the client meeting?',a:'Start with the publications behind the additional articles. Check whether the increase came from outlets with lower estimated reach, then look at which topics drove that coverage.',stat:'Next question: which outlets explain the shift?',caution:'That’s an investigation to run, not a proven explanation. Review the underlying articles before recommending a change.',source:'This scripted recommendation follows the fictional volume and reach comparison. No publication-level finding is claimed, and no live AI request is made.'}];function showChat(i){let c=chatExamples[i];$('#chat-question').textContent=c.q;$('#chat-answer').textContent=c.a;$('#chat-stat').textContent=c.stat;$('#chat-caution').textContent=c.caution;$('#chat-source').textContent=c.source;$$('[data-prompt]').forEach(b=>{b.classList.toggle('active',+b.dataset.prompt===i);b.setAttribute('aria-pressed',+b.dataset.prompt===i)})}$$('[data-prompt]').forEach(b=>b.onclick=()=>showChat(+b.dataset.prompt));showChat(0);
const motionQuery=matchMedia('(prefers-reduced-motion: reduce)');let motionEnabled=!motionQuery.matches;const motionButton=document.createElement('button');motionButton.className='motion-toggle';motionButton.type='button';document.body.append(motionButton);const layers=$$('[data-parallax]');let framePending=false;function paintMotion(){framePending=false;const mobile=innerWidth<761;layers.forEach(el=>{if(!motionEnabled){el.style.setProperty('--parallax-y','0px');return}const box=el.parentElement.getBoundingClientRect();const offset=Math.max(-140,Math.min(140,(innerHeight*.5-(box.top+box.height*.5))*Number(el.dataset.parallax)*(mobile?.45:1)));el.style.setProperty('--parallax-y',offset.toFixed(1)+'px')})}function scheduleMotion(){if(!framePending){framePending=true;requestAnimationFrame(paintMotion)}}function motionState(){document.body.classList.toggle('motion-paused',!motionEnabled);motionButton.textContent=motionEnabled?'◉ Motion on':'○ Motion off';motionButton.setAttribute('aria-pressed',String(motionEnabled));motionButton.setAttribute('aria-label',motionEnabled?'Turn animation and parallax off':'Turn animation and parallax on');scheduleMotion()}motionButton.onclick=()=>{motionEnabled=!motionEnabled;motionState()};motionQuery.addEventListener('change',()=>{motionEnabled=!motionQuery.matches;motionState()});addEventListener('scroll',scheduleMotion,{passive:true});addEventListener('resize',scheduleMotion,{passive:true});motionState();
if(!motionQuery.matches&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});$$('.section-head,.trust-grid article,.difference-grid article,.context-story>h2').forEach(el=>{el.classList.add('motion-reveal');observer.observe(el)})}
const mapStories={inputs:['REPORTS ARRIVE','Start with the files your provider sends.','Bring monthly reports, campaign coverage, and historical Excel batches into a project. PR Iris analyzes that supplied coverage; the monitoring provider collects it.','#data-sources','See how mentions are labeled ↘'],project:['ONE SHARED PROJECT','Keep the reporting context together.','Retain batches in one workspace, then choose the files and periods for the question. That shared base connects the analysis, saved conversations, and reporting outputs.','#assistant','Meet the assistant ↘'],sentiment:['FOLLOWING THE SENTIMENT BRANCH','What is the tone—and what kind of article is it?','Sentiment and article-type labels give the coverage structure. Your team reviews the classifications before using them to explain performance.','#data-sources','See a mention example ↘'],relevance:['FOLLOWING THE RELEVANCE BRANCH','A mention is not always a meaningful story.','Distinguish a passing brand reference from substantive coverage. Review the source before treating that label as evidence of value.','#data-sources','Compare the two examples ↘'],source:['FOLLOWING THE SOURCE BRANCH','Where did the coverage come from?','Source labels such as social, owned, and earned media add context to the coverage. Check the source mix when interpreting the overall picture.','#experience','Explore the coverage ↘'],compare:['FOLLOWING THE COMPARISON BRANCH','Find the change behind the headline number.','Compare periods, brands, and publications. Share of voice, article volume, and estimated reach help frame the performance story.','#experience','Try the comparison ↘'],chat:['FOLLOWING THE AI BRANCH','Ask a question. Keep the context.','Ask the assistant about the selected batches and follow up. Reopen saved sessions, check the evidence, and distinguish observations from hypotheses.','#assistant','Try a follow-up ↘'],review:['THE HUMAN CHECKPOINT','You decide what the evidence supports.','Check classifications, files, dates, and the interpretation. If something is unclear, return to the sources or ask a sharper question before recommending an action.','#why-not-claude','Why use a dedicated workspace? ↘'],charts:['THE PERFORMANCE STORY','Make the change easy to explain.','Use charts and comparisons to show where coverage moved. Estimated reach is potential exposure—not unique people reached or proven revenue.','#experience','Explore the chart ↘'],exports:['TAKE THE ANALYSIS INTO THE MEETING','Use the work in Excel and PowerPoint.','Project and comparison exports support client reporting. Editorialized presentations from selected Chat exchanges remain on the roadmap.','#value','Calculate the reporting value ↘'],brief:['YOUR TEAM’S NEXT MOVE','Turn reviewed findings into a better brief.','Use the analysis to shape priorities and recommendations for the next campaign. Your team writes the strategy; the workspace supplies context and evidence.','#outcomes','See the desired outcomes ↘']};let mapSelection='sentiment';const analysisNodes=['sentiment','relevance','source','compare','chat'];const inputNodes=['monthly','campaign','history'];const outputNodes=['charts','exports','brief'];const mapEdges=[...inputNodes.map(x=>[x,'project']),...analysisNodes.map(x=>['project',x]),...analysisNodes.map(x=>[x,'review']),...outputNodes.map(x=>['review',x])];function drawMap(){const canvas=$('#map-canvas'),svg=canvas.querySelector('svg'),rect=canvas.getBoundingClientRect(),mobile=innerWidth<=760;svg.setAttribute('viewBox',`0 0 ${rect.width} ${rect.height}`);svg.innerHTML=mapEdges.map(([a,b])=>{const ra=canvas.querySelector(`[data-node="${a}"]`).getBoundingClientRect(),rb=canvas.querySelector(`[data-node="${b}"]`).getBoundingClientRect();let x1,y1,x2,y2,d;if(mobile){x1=ra.left+ra.width/2-rect.left;y1=ra.bottom-rect.top;x2=rb.left+rb.width/2-rect.left;y2=rb.top-rect.top;const m=(y1+y2)/2;d=`M${x1},${y1} C${x1},${m} ${x2},${m} ${x2},${y2}`}else{x1=ra.right-rect.left;y1=ra.top+ra.height/2-rect.top;x2=rb.left-rect.left;y2=rb.top+rb.height/2-rect.top;const m=(x1+x2)/2;d=`M${x1},${y1} C${m},${y1} ${m},${y2} ${x2},${y2}`}const selective=analysisNodes.includes(mapSelection);let lit=!selective||a===mapSelection||b===mapSelection||inputNodes.includes(a)||a==='review';return `<path class="map-wire ${lit?'lit':''} ${analysisNodes.includes(a)||analysisNodes.includes(b)?'ai':''}" d="${d}"/>`}).join('')};function selectMap(route){mapSelection=route;const s=mapStories[route];$('#map-kicker').textContent=s[0];$('#map-title').textContent=s[1];$('#map-copy').textContent=s[2];$('#map-deeper').href=s[3];$('#map-deeper').textContent=s[4];$$('[data-route]').forEach(b=>{const active=b.dataset.route===route;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);b.classList.toggle('on-route',['project','review'].includes(b.dataset.node))});drawMap()}$$('[data-route]').forEach(b=>b.onclick=()=>selectMap(b.dataset.route));selectMap('sentiment');new ResizeObserver(drawMap).observe($('#map-canvas'));document.fonts.ready.then(drawMap);
